INSERT INTO seed_text VALUES
    ('review', 5, 'el', 'Τέλειος, όπως πάντα!'),
    ('review', 5, 'el', 'Ο μάστορας ξέρει τι κάνει. Το καλύτερο fade που έχω κάνει ποτέ.'),
    ('review', 5, 'el', 'Πολύ καθαρός χώρος, φιλικά παιδιά και ακριβώς στην ώρα του ραντεβού.'),
    ('review', 5, 'el', 'Δέκα με τόνο.'),
    ('review', 5, 'el', 'Πήγα για πρώτη φορά μετά από σύσταση φίλου και δεν αλλάζω κουρείο. Άκουσε τι ήθελα και το έκανε ακόμα καλύτερο.'),
    ('review', 5, 'el', 'Το ξύρισμα με τη ζεστή πετσέτα αξίζει κάθε ευρώ.'),
    ('review', 5, 'el', 'Ο γιος μου φοβόταν τα κουρεία, αλλά εδώ έφυγε χαμογελαστός. Τεράστια υπομονή!'),
    ('review', 5, 'el', 'Άψογη δουλειά στα γένια.'),
    ('review', 5, 'el', 'Μπήκα στην ώρα μου, βγήκα σε μισή ώρα, τέλειο αποτέλεσμα.'),
    ('review', 5, 'el', 'Εξαιρετική εξυπηρέτηση, καφεδάκι και καλή κουβέντα.'),
    ('review', 5, 'el', 'Επιτέλους ένα κουρείο που καταλαβαίνει τα σγουρά μαλλιά.'),
    ('review', 5, 'el', 'Κορυφή!'),
    ('review', 5, 'el', 'Πηγαίνω χρόνια και δεν με έχει απογοητεύσει ούτε μία φορά.'),
    ('review', 5, 'el', 'Λεπτομέρεια σε κάθε γραμμή. Φαίνεται ότι αγαπάει τη δουλειά του.'),
    ('review', 5, 'el', 'Πολύ καλές τιμές για την ποιότητα που παίρνεις.'),
    ('review', 5, 'el', 'Το online ραντεβού δούλεψε άψογα και ήρθε και υπενθύμιση. Το κούρεμα, όπως πάντα, πολύ καλό.'),
    ('review', 5, 'el', 'Καθαριότητα, επαγγελματισμός, χαμόγελο.'),
    ('review', 5, 'el', 'Μου έφτιαξε το σχήμα στα γένια που ήθελα εδώ και μήνες.'),
    ('review', 5, 'el', 'Ήρθα με τον μπαμπά μου και φύγαμε και οι δύο ευχαριστημένοι.'),
    ('review', 5, 'el', 'Ό,τι καλύτερο έχει η γειτονιά.'),
    ('review', 5, 'el', 'Γρήγορος, προσεκτικός και πάντα στην ώρα του.'),
    ('review', 5, 'el', 'Το grey blending βγήκε τόσο φυσικό που δεν το κατάλαβε κανείς. Ακριβώς αυτό ήθελα.'),
    ('review', 5, 'el', 'Ωραία ατμόσφαιρα, καλή μουσική και κορυφαίο fade.'),
    ('review', 5, 'el', 'Πολύ ευγενικοί όλοι. Θα ξαναέρθω σίγουρα.'),
    ('review', 5, 'el', 'Από τα λίγα μέρη που σε ρωτάνε πριν κόψουν.'),
    ('review', 5, 'el', 'Πέντε αστέρια χωρίς δεύτερη σκέψη.'),
    ('review', 5, 'el', 'Τρεις εβδομάδες μετά και το κούρεμα φαίνεται ακόμα φρέσκο. Αυτό λέει πολλά.'),
    ('review', 5, 'el', 'Ο μάστορας είναι καλλιτέχνης.'),
    ('review', 5, 'el', 'Ήμουν στην πόλη για δουλειά και βρήκα ραντεβού την ίδια μέρα. Πολύ καλή εμπειρία.'),
    ('review', 5, 'el', 'Πάντα καθαρά εργαλεία και φρέσκες πετσέτες. Για μένα αυτό μετράει.'),
    ('review', 5, 'el', 'Τα παιδιά είναι φοβεροί. Σκέτη απόλαυση!'),
    ('review', 5, 'el', 'Το καλύτερο κούρεμα της ζωής μου και δεν υπερβάλλω.'),
    ('review', 4, 'el', 'Πολύ καλό κούρεμα, απλώς περίμενα δέκα λεπτά παραπάνω.'),
    ('review', 4, 'el', 'Καλή δουλειά, λίγο ακριβό για τα δεδομένα της περιοχής.'),
    ('review', 4, 'el', 'Ευχάριστος χώρος και καλός μάστορας. Το πάρκινγκ είναι δύσκολο.'),
    ('review', 4, 'el', 'Ωραίο αποτέλεσμα στα γένια. Το κούρεμα ήθελε λίγη ακόμα δουλειά στο πίσω μέρος.'),
    ('review', 4, 'el', 'Πολύ καλό.'),
    ('review', 4, 'el', 'Σταθερή αξία, χωρίς εκπλήξεις.'),
    ('review', 4, 'el', 'Καλή εξυπηρέτηση, αλλά η μουσική ήταν πολύ δυνατή.'),
    ('review', 4, 'el', 'Το fade ήταν καθαρό. Θα ήθελα λίγο περισσότερο χρόνο στο styling.'),
    ('review', 4, 'el', 'Καλός, γρήγορος, φιλικός. Θα ξαναπάω.'),
    ('review', 4, 'el', 'Μου άρεσε, αν και το Σάββατο ήταν αρκετά γεμάτο.'),
    ('review', 4, 'el', 'Καλό κούρεμα σε λογική τιμή.'),
    ('review', 4, 'el', 'Όλα καλά, απλώς το ραντεβού ξεκίνησε με μικρή καθυστέρηση.'),
    ('review', 4, 'el', 'Ευγενικοί και επαγγελματίες. Λίγος θόρυβος από τον δρόμο.'),
    ('review', 4, 'el', 'Αρκετά καλό, πολύ κοντά σε αυτό που ζήτησα.'),
    ('review', 4, 'el', 'Ο νέος μπαρμπέρης τα πήγε πολύ καλά. Του λείπει λίγη εμπειρία στο ψαλίδι.'),
    ('review', 4, 'el', 'Ωραίο ξύρισμα, η πετσέτα θα μπορούσε να είναι πιο ζεστή.'),
    ('review', 4, 'el', 'Καθαρό μαγαζί, καλές τιμές.'),
    ('review', 4, 'el', 'Ικανοποιημένος. Θα ήθελα περισσότερες ελεύθερες ώρες το απόγευμα.'),
    ('review', 4, 'el', 'Καλή δουλειά στο παιδικό, αλλά ο μικρός βαρέθηκε λίγο στην αναμονή.'),
    ('review', 4, 'el', 'Πολύ καλός ο μάστορας. Το προϊόν για το styling δεν μου άρεσε τόσο.'),
    ('review', 3, 'el', 'Μέτριο.'),
    ('review', 3, 'el', 'Το κούρεμα ήταν οκ, αλλά περίμενα 25 λεπτά παρότι είχα ραντεβού.'),
    ('review', 3, 'el', 'Τίποτα το ιδιαίτερο για αυτή την τιμή.'),
    ('review', 3, 'el', 'Καλός μπαρμπέρης, αλλά βιαστικός.'),
    ('review', 3, 'el', 'Δεν ήταν ακριβώς αυτό που ζήτησα, αλλά δεν ήταν και κακό.'),
    ('review', 3, 'el', 'Ο χώρος θέλει λίγο περισσότερη καθαριότητα.'),
    ('review', 3, 'el', 'Αξιοπρεπές κούρεμα, τίποτα παραπάνω.'),
    ('review', 3, 'el', 'Τα γένια βγήκαν λίγο ασύμμετρα. Το κούρεμα καλό.'),
    ('review', 3, 'el', 'Καλή εξυπηρέτηση, μέτριο αποτέλεσμα.'),
    ('review', 3, 'el', 'Λίγο ακριβό για αυτό που πήρα.'),
    ('review', 3, 'el', 'Άλλαξαν μπαρμπέρη χωρίς να με ενημερώσουν. Το αποτέλεσμα ήταν εντάξει.'),
    ('review', 3, 'el', 'Ούτε καλό ούτε κακό. Μάλλον θα δοκιμάσω και αλλού.'),
    ('review', 2, 'el', 'Πολλή αναμονή και βιαστική δουλειά.'),
    ('review', 2, 'el', 'Το fade είχε εμφανή σκαλοπάτια. Δεν θα ξαναπάω σύντομα.'),
    ('review', 2, 'el', 'Με χρέωσαν περισσότερα από την τιμή που έγραφε η εφαρμογή.'),
    ('review', 2, 'el', 'Δεν άκουσε τι ζήτησα και το έκοψε πολύ πιο κοντά.'),
    ('review', 2, 'el', 'Βρώμικες πετσέτες και τρίχες παντού στον πάγκο.'),
    ('review', 2, 'el', 'Ήρθα στην ώρα μου και με έβαλαν μετά από δύο άλλους.'),
    ('review', 2, 'el', 'Αγενής συμπεριφορά στο ταμείο.'),
